internal static class GuideSoloConductorCommand
{
    internal const string CommandName = "intent-cli guide solo-conductor";
    internal const string ContractVersion = "g833-solo-conductor/v1";
    internal const string ToolIntentCli = "intent-cli";
    internal const string ToolGh = "gh";
    internal const string ToolGit = "git";
    private const string FormatJson = "json";
    private const string FormatMarkdown = "markdown";
    private const string RuntimePlaceholder = "<codex|claude|cursor|copilot|opencode>";
    private const string ModelRequiredPrefix = "The model is required. ";
    private const string UsageLine =
        "Usage: intent-cli guide solo-conductor [--format markdown|json]";

    private static readonly string[] BuilderContractItems =
    [
        "The conductor runs one builder at a time in the unit's isolated clone (step 6). Clones are kept outside every runtime's trusted folders. The copilot builder line runs with its own fresh, empty `COPILOT_HOME` and `XDG_CONFIG_HOME` for each run, which the conductor creates (for example with `mktemp -d`) and removes afterwards, so the operator's Copilot trust settings, hooks, and MCP servers never apply to it. The guide stays metadata-free and reads no configuration.",
        "The task prompt is a file the conductor writes and passes on stdin, except cursor, which takes it as an argument. Any OpenCode command shown without a prompt file carries `< /dev/null`: with stdin left open, `opencode run` waits and prints nothing (measured over five minutes), and a background run started from a script hangs the same way.",
        "The builder may edit and commit inside the clone and never pushes, opens a PR, or runs `gh`. The conductor pushes, opens the PR, and owns claims and transitions.",
        "What bounds the builder differs by runtime, and no measured builder invocation sandboxes shell commands, so the conductor reviews the clone's diff before pushing.",
        "The OpenCode builder line runs with fresh, empty `XDG_CONFIG_HOME` and `OPENCODE_CONFIG_DIR` directories per run, created by the conductor. The clone's project config and `AGENTS.md` are not loaded in this form, so the task file carries every repository instruction the builder needs. A provider defined only in the operator's global config goes into the builder config file (the `provider` block after `$schema`, as for the reviewer).",
        "A local model provider serves one seat at a time. Do not start a local-model builder or reviewer while another local-model seat runs; intent-cli does not check this.",
        "intent-cli renders these lines and never launches a builder, a reviewer, or an AI provider CLI. The review commands' only launch is the existing claim-read `git fetch`.",
    ];

    internal static int Execute(CliContext context, string[] args, TextWriter writer)
    {
        ArgumentNullException.ThrowIfNull(context);
        ArgumentNullException.ThrowIfNull(args);
        ArgumentNullException.ThrowIfNull(writer);

        if (args.Length == 1 && string.Equals(args[0], "--help", StringComparison.Ordinal))
        {
            WriteHelp(writer);
            return 0;
        }

        if (!TryParseFormat(args, out var format, out var error))
        {
            writer.WriteLine(error);
            writer.WriteLine(UsageLine);
            return 1;
        }

        var guide = BuildGuide();
        if (string.Equals(format, FormatJson, StringComparison.Ordinal))
        {
            writer.WriteLine(JsonSerializer.Serialize(guide, JsonOptions));
        }
        else
        {
            WriteMarkdown(writer, guide);
        }

        return 0;
    }

    private static SoloConductorCommand IntentCli(string command) => new() { Tool = ToolIntentCli, Command = command };

    private static SoloConductorCommand Gh(string command) => new() { Tool = ToolGh, Command = command };

    private static SoloConductorCommand Git(string command) => new() { Tool = ToolGit, Command = command };

    internal static SoloConductorBuilder BuildBuilder() => new()
